// Normalize the inbound WhatsApp Cloud API webhook payload, safely extract the
// first inbound text message, and classify it with deterministic, word/phrase-aware
// keyword routing. This is a template for demonstration/testing -- adapt keywords
// and languages to your own business before production use.
//
// NOTE: this endpoint is POST-only. It does NOT implement Meta's required GET
// verification handshake or X-Hub-Signature-256 signature validation. Test it
// with any synthetic HTTP client; do not point Meta's webhook config at it
// as-is -- see this workflow's documentation for what a production setup needs.

const item = $input.first().json;
const payload = item.body !== undefined ? item.body : item;

function safeGet(obj, path, fallback) {
  try {
    let cur = obj;
    for (const key of path) {
      if (cur === null || cur === undefined) return fallback;
      cur = cur[key];
    }
    return cur === undefined ? fallback : cur;
  } catch (e) {
    return fallback;
  }
}

// Word/phrase-aware matcher: uses \b boundaries so "book" won't match inside
// "Facebook" and "bill" won't match inside "billion". Multi-word phrases (e.g.
// "not working") match as a phrase with flexible whitespace between words.
function buildMatcher(keyword) {
  const escaped = keyword.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const pattern = escaped.includes(' ') ? escaped.replace(/ /g, '\\s+') : escaped;
  return new RegExp('\\b' + pattern + '\\b');
}

function matchesAny(text, keywords) {
  return keywords.some((k) => buildMatcher(k).test(text));
}

let result;

try {
  if (!payload || typeof payload !== 'object') {
    result = { route: null, messageType: 'malformed', status: 'ignored' };
  } else {
    const entry = safeGet(payload, ['entry', 0], null);
    const change = entry ? safeGet(entry, ['changes', 0], null) : null;
    const value = change ? safeGet(change, ['value'], null) : null;

    if (!value) {
      result = { route: null, messageType: 'malformed', status: 'ignored' };
    } else {
      const messages = Array.isArray(value.messages) ? value.messages : [];
      const statuses = Array.isArray(value.statuses) ? value.statuses : [];

      if (messages.length === 0) {
        if (statuses.length > 0) {
          result = { route: null, messageType: 'status_event', status: 'ignored' };
        } else {
          result = { route: null, messageType: 'malformed', status: 'ignored' };
        }
      } else {
        const firstMessage = messages[0];
        const msgType = firstMessage.type;
        const text = msgType === 'text' ? safeGet(firstMessage, ['text', 'body'], '') : '';

        if (msgType !== 'text' || !text || typeof text !== 'string' || text.trim() === '') {
          result = { route: null, messageType: msgType || 'unknown', status: 'ignored' };
        } else {
          const normalized = text.trim().toLowerCase();

          // Deterministic keyword routing -- not AI/ML. Adapt to your language(s)
          // and vocabulary; this is a starting template, not a finished classifier.
          const KEYWORDS = {
            appointments: ['appointment', 'book', 'booking', 'schedule', 'reschedule', 'reserve', 'reservation'],
            billing: ['invoice', 'bill', 'billing', 'payment', 'pay', 'charge', 'refund', 'receipt', 'subscription'],
            support: ['help', 'support', 'issue', 'problem', 'not working', 'broken', 'error', 'trouble'],
          };

          let route = 'general';
          for (const [category, keywords] of Object.entries(KEYWORDS)) {
            if (matchesAny(normalized, keywords)) {
              route = category;
              break;
            }
          }

          result = { route, messageType: 'text', status: 'classified' };
        }
      }
    }
  }
} catch (err) {
  result = { route: null, messageType: 'malformed', status: 'ignored' };
}

return [{ json: result }];
